insert into public.exercise_catalog (id,data,published) values
('shoulder-tap','{"id":"shoulder-tap","name":"Plancha con toque de hombro","aliases":[],"purpose":"Resistir la rotación del tronco al cambiar el apoyo.","steps":["Apoya las manos bajo los hombros y separa los pies. Forma una línea estable entre cabeza, cadera y talones.","Despega una mano y toca el hombro contrario sin desplazar la pelvis. Exhala suavemente.","Vuelve a apoyar y alterna el brazo. Cuenta cada toque; reduce la velocidad si la cadera se balancea."],"mistake":"Girar la pelvis o hundir la zona lumbar para alcanzar el hombro.","learn":"Empieza con manos sobre un banco estable o rodillas apoyadas.","image":{"src":"/training/core-footwork.png","tile":0,"columns":4,"rows":3},"version":1}'::jsonb,true),
('short-crunch','{"id":"short-crunch","name":"Crunch corto con pies apoyados","aliases":[],"purpose":"Flexión controlada del tronco con recorrido pequeño.","steps":["Túmbate boca arriba, rodillas flexionadas y pies apoyados. Mantén la mirada hacia arriba y brazos junto al cuerpo.","Exhala y acerca suavemente las costillas a la pelvis, elevando solo la parte alta de la espalda.","Baja despacio, sin tirar del cuello ni convertir el movimiento en una incorporación completa."],"mistake":"Impulsarte con la cabeza o buscar altura en vez de control abdominal.","learn":"Ensaya sin carga y con un recorrido corto, cómodo.","image":{"src":"/training/core-footwork.png","tile":1,"columns":4,"rows":3},"version":1}'::jsonb,true),
('bird-dog','{"id":"bird-dog","name":"Bird dog contralateral","aliases":[],"purpose":"Control de tronco y pelvis mientras se mueven brazo y pierna opuestos.","steps":["Coloca manos bajo hombros y rodillas bajo caderas. Mantén cuello y espalda neutrales.","Alarga un brazo y la pierna contraria hasta la altura del tronco, sin levantar la cadera.","Pausa dos segundos, vuelve con control y cambia de lado. Sigue respirando."],"mistake":"Arquear la espalda o abrir la pelvis al elevar la pierna.","learn":"Practica primero moviendo solo el brazo o solo la pierna.","image":{"src":"/training/core-footwork.png","tile":2,"columns":4,"rows":3},"version":1}'::jsonb,true),
('crunch-hold','{"id":"crunch-hold","name":"Isométrico abdominal con pies apoyados","aliases":[],"purpose":"Mantener tensión abdominal con respiración y un recorrido reducido.","steps":["Túmbate con rodillas flexionadas y pies en el suelo; alarga los brazos hacia los muslos.","Eleva ligeramente los omóplatos acercando costillas a pelvis, sin despegar la zona lumbar.","Mantén la posición durante el tiempo indicado respirando; apoya la cabeza y descansa entre series."],"mistake":"Bloquear la respiración o tensar el cuello para sostenerte.","learn":"Empieza con 10 segundos y reduce el tiempo si se pierde la posición.","image":{"src":"/training/core-footwork.png","tile":3,"columns":4,"rows":3},"version":1}'::jsonb,true),
('pogo-hop','{"id":"pogo-hop","name":"Rebotes de tobillo a dos pies","aliases":[],"purpose":"Introducir contactos breves de baja amplitud y control del apoyo.","steps":["De pie, pies paralelos y separados a anchura de caderas; rodillas ligeramente desbloqueadas.","Haz pequeños rebotes verticales desde los tobillos. Despega pocos centímetros y mantén el tronco alto.","Contacta de forma silenciosa y regular. Para si los apoyos se vuelven pesados o aparece molestia."],"mistake":"Buscar altura máxima, bloquear las rodillas o aterrizar sobre el borde del pie.","learn":"Primero domina elevaciones de talón y aterrizajes suaves. No se hace con lastre.","image":{"src":"/training/core-footwork.png","tile":4,"columns":4,"rows":3},"version":1}'::jsonb,true),
('line-hop','{"id":"line-hop","name":"Saltos laterales bajos sobre línea","aliases":[],"purpose":"Coordinar pequeños impulsos laterales y aterrizajes repetidos.","steps":["Marca una línea en suelo plano y sitúate a un lado con ambos pies juntos, rodillas flexibles.","Salta unos centímetros al otro lado con los dos pies a la vez, sin inclinar excesivamente el tronco.","Repite al ritmo que permita apoyos suaves. Cada salto cuenta como un contacto; descansa antes de perder control."],"mistake":"Separar las rodillas de la dirección de los pies o convertirlo en un esfuerzo hasta el agotamiento.","learn":"Empieza con pasos laterales sobre la línea y después saltos aislados.","image":{"src":"/training/core-footwork.png","tile":5,"columns":4,"rows":3},"version":1}'::jsonb,true),
('broad-jump','{"id":"broad-jump","name":"Salto horizontal con estabilización","aliases":[],"purpose":"Producir impulso horizontal y absorber el aterrizaje con control.","steps":["Comprueba que tienes suelo antideslizante y espacio libre delante. Flexiona cadera y rodillas llevando brazos atrás.","Empuja el suelo con los dos pies y acompaña con los brazos hacia delante.","Aterriza con ambos pies, cadera y rodillas flexionadas; mantén la posición dos segundos y recolócate antes del siguiente salto."],"mistake":"Perseguir distancia perdiendo equilibrio o enlazar saltos sin estabilizar.","learn":"Usa una distancia corta y evita intentos máximos hasta dominar el aterrizaje.","image":{"src":"/training/core-footwork.png","tile":6,"columns":4,"rows":3},"version":1}'::jsonb,true),
('split-jump','{"id":"split-jump","name":"Salto en zancada con cambio","aliases":[],"purpose":"Potencia unilateral alterna para quien ya controla saltos y zancadas.","steps":["Adopta una zancada estable con separación lateral entre pies, rodillas alineadas y tronco erguido.","Impulsa suavemente hacia arriba y cambia la posición de las piernas en el aire.","Aterriza amortiguando en zancada, estabiliza y repite con amplitud baja. Cuenta cada cambio."],"mistake":"Cerrar los pies en una línea o hundir la rodilla hacia dentro al aterrizar.","learn":"Ejercicio avanzado: domina primero la zancada sin salto. No añadas peso.","image":{"src":"/training/core-footwork.png","tile":7,"columns":4,"rows":3},"version":1}'::jsonb,true),
('cone-shuffle','{"id":"cone-shuffle","name":"Desplazamiento lateral entre conos","aliases":[],"purpose":"Mover la base de apoyo manteniendo equilibrio y guardia.","steps":["Coloca dos marcas separadas unos dos metros y adopta tu guardia habitual, rodillas flexibles.","Muévete lateralmente iniciando con el pie del lado al que vas; el otro recupera la distancia de guardia.","Frena antes de la marca y vuelve sin cruzar ni juntar los pies. Prioriza precisión y aumenta ritmo gradualmente."],"mistake":"Cruzar las piernas, rebotar en exceso o perder la guardia para ir más rápido.","learn":"Puedes usar dos marcas en el suelo; no necesitas conos.","image":{"src":"/training/core-footwork.png","tile":8,"columns":4,"rows":3},"version":1}'::jsonb,true),
('ladder-two','{"id":"ladder-two","name":"Escalera de coordinación: dos apoyos","aliases":[],"purpose":"Practicar ritmo y precisión de apoyos; no sustituye el trabajo táctico del ring.","steps":["Extiende una escalera plana o marca casillas en el suelo. Colócate frente a la primera, con guardia relajada.","Introduce un pie y después el otro en cada casilla, avanzando una casilla cada dos apoyos.","Mantén contactos ligeros y mirada al frente cuando domines el recorrido. Sal, camina y reinicia; alterna el pie que inicia."],"mistake":"Acelerar hasta pisar las cintas o mirar siempre hacia abajo.","learn":"Practica despacio con casillas amplias antes de aumentar velocidad.","image":{"src":"/training/core-footwork.png","tile":9,"columns":4,"rows":3},"version":1}'::jsonb,true),
('boxing-in-out','{"id":"boxing-in-out","name":"Entrada y salida en guardia","aliases":[],"purpose":"Controlar la distancia conservando la base de apoyo.","steps":["Adopta tu guardia habitual, pies separados y peso equilibrado. Usa una marca en el suelo como referencia.","Para entrar, avanza primero el pie delantero y recupera la separación con el trasero.","Para salir, retrocede primero el pie trasero y acompaña con el delantero. Mantén guardia y pasos cortos; una entrada y salida es una repetición."],"mistake":"Juntar los pies, cruzarlos o inclinarte hacia el objetivo en lugar de desplazar la base.","learn":"Ensaya sin golpes y pide al entrenador que revise tu guardia.","image":{"src":"/training/core-footwork.png","tile":10,"columns":4,"rows":3},"version":1}'::jsonb,true),
('boxing-pivot','{"id":"boxing-pivot","name":"Pivote de cuarto de vuelta en guardia","aliases":[],"purpose":"Cambiar el ángulo conservando equilibrio y orientación de la guardia.","steps":["Desde tu guardia, descarga ligeramente el pie posterior y mantén el delantero cerca del punto de referencia.","Gira sobre la parte delantera del apoyo delantero permitiendo que rodilla y pie acompañen; el trasero dibuja un arco pequeño.","Recupera una base estable mirando hacia el nuevo ángulo. Practica a ambos lados sin forzar la amplitud."],"mistake":"Mantener el pie clavado y retorcer la rodilla, o cruzar las piernas.","learn":"Empieza con un giro pequeño y lento, revisado por tu entrenador.","image":{"src":"/training/core-footwork.png","tile":11,"columns":4,"rows":3},"version":1}'::jsonb,true)
