-- Reusable public instructional content only. RLS and grants are unchanged.
begin;
on conflict (id) do update set data=excluded.data,published=excluded.published,updated_at=now();
commit;
select count(*) as illustrated_exercises, count(*) filter (where data->'image'->>'src'='/training/core-footwork.png') as new_movements from public.exercise_catalog where published;
